// modified version of
// https://github.com/causaly/zod-validation-error/blob/main/lib/fromZodError.ts
// https://github.com/causaly/zod-validation-error/blob/main/lib/fromZodIssue.ts
export function fromZodError(zodError) {
    const zodIssues = zodError.errors;
    return zodIssues.length === 0
        ? zodError.message
        : zodIssues.map((issue) => getMessageFromZodIssue(issue)).join("\n");
}
function formatValuesToList(values) {
    return values.map((s) => `\n- "${s}"`).join("");
}
function getMessageFromZodIssue(issue) {
    let message = issue.message;
    if (issue.code === "invalid_type") {
        message = `Expected ${issue.expected}, received ${issue.received}`;
    }
    if (issue.code === "invalid_enum_value") {
        const sortedGuesses = sortByClosest(String(issue.received), issue.options.map(String));
        const guess = sortedGuesses[0];
        if (sortedGuesses.length > 6) {
            message = `Invalid enum value "${issue.received}". Did you mean "${guess}"?
Other similar accepted values: ${formatValuesToList(sortedGuesses.slice(1, 6))}
- (...${sortedGuesses.length - 6} more)`;
        }
        else {
            message = `Invalid enum value "${issue.received}". Did you mean "${guess}"?
Accepted enum values: ${formatValuesToList(sortedGuesses)}`;
        }
    }
    if (issue.code === "invalid_union") {
        message = issue.unionErrors
            .reduce((acc, zodError) => {
            const newIssues = zodError.issues
                .map(getMessageFromZodIssue)
                .join("\n");
            if (!acc.includes(newIssues)) {
                acc.push(newIssues);
            }
            return acc;
        }, [])
            .join("\n");
        // for enums, return the enum message before prefixing it wtih the path part, it's already there from the union
        return message;
    }
    if (issue.path.length > 0) {
        // handle array indices
        if (issue.path.length === 1) {
            const identifier = issue.path[0];
            if (typeof identifier === "number") {
                return `index ${identifier}: ${message}`;
            }
        }
        return `"${joinPath(issue.path)}" prop is invalid: ${message}`;
    }
    return message;
}
const identifierRegex = /[$_\p{ID_Start}][$\u200c\u200d\p{ID_Continue}]*/u;
export function joinPath(path) {
    if (path.length === 1) {
        return path[0].toString();
    }
    return path.reduce((acc, item) => {
        // handle numeric indices
        if (typeof item === "number") {
            return acc + "[" + item.toString() + "]";
        }
        // handle quoted values
        if (item.includes('"')) {
            return acc + '["' + escapeQuotes(item) + '"]';
        }
        // handle special characters
        if (!identifierRegex.test(item)) {
            return acc + '["' + item + '"]';
        }
        // handle normal values
        const separator = acc.length === 0 ? "" : ".";
        return acc + separator + item;
    }, "");
}
function escapeQuotes(str) {
    return str.replace(/"/g, '\\"');
}
function escapeRegExp(text) {
    return text.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, "\\$&");
}
function levenshteinDistance(word1, word2) {
    const m = word1.length;
    const n = word2.length;
    const dp = [];
    for (let i = 0; i <= m; i++) {
        dp[i] = [];
        dp[i][0] = i;
    }
    for (let j = 0; j <= n; j++) {
        dp[0][j] = j;
    }
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            const cost = word1[i - 1] === word2[j - 1] ? 0 : 1;
            dp[i][j] = Math.min(dp[i - 1][j] + 1, // deletion
            dp[i][j - 1] + 1, // insertion
            dp[i - 1][j - 1] + cost // substitution
            );
        }
    }
    return dp[m][n];
}
function sortByClosest(targetWord, wordSet) {
    return wordSet
        .map((word) => ({ word, distance: levenshteinDistance(targetWord, word) }))
        .sort((a, b) => a.distance - b.distance)
        .map(({ word }) => word);
}
